#!/usr/bin/env python3
"""
Test script to reproduce and verify the DNS-1123 compliance issue.
"""

import re
from metadata_converter.generate import generate_dlf_yaml_dict
from ruamel.yaml import YAML

yaml = YAML()

def is_dns_1123_subdomain_compliant(name):
    """
    Check if a name complies with DNS-1123 subdomain naming conventions.

    DNS-1123 subdomain must consist of lower case alphanumeric characters, '-' or '.',
    and must start and end with an alphanumeric character.

    Regex: '[a-z0-9]([-a-z0-9]*[a-z0-9])?(\.[a-z0-9]([-a-z0-9]*[a-z0-9])?)*'
    """
    if not isinstance(name, str):
        return False

    pattern = r'^[a-z0-9]([-a-z0-9]*[a-z0-9])?(\.[a-z0-9]([-a-z0-9]*[a-z0-9])?)*$'
    return bool(re.match(pattern, name))

def test_problematic_datasets():
    """Test datasets that currently violate DNS-1123 naming conventions."""

    test_cases = [
        {
            'file': 'dax-data-set-descriptors/finance_proposition_bank.yaml',
            'expected_original_name': 'Finance Proposition Bank'
        },
        {
            'file': 'dax-data-set-descriptors/gmb.yaml',
            'expected_original_name': 'Groningen Meaning Bank – Modified'
        },
        {
            'file': 'dax-data-set-descriptors/jfk.yaml', 
            'expected_original_name': 'NOAA Weather Data – JFK Airport'
        },
        {
            'file': 'dax-data-set-descriptors/lorem_ipsum.yaml',
            'expected_original_name': 'Lorem ipsum data set'
        },
        {
            'file': 'dax-data-set-descriptors/thematic_clustering.yaml',
            'expected_original_name': 'IBM Debater® Thematic Clustering of Sentences'
        }
    ]

    print("Testing DNS-1123 compliance of generated DLF YAML...")
    print("=" * 60)

    for test_case in test_cases:
        try:
            # Load the input YAML
            input_yaml = yaml.load(open(test_case['file']))
            original_name = input_yaml['name']

            # Generate DLF YAML
            dlf_dict = generate_dlf_yaml_dict(input_yaml)
            generated_name = dlf_dict['metadata']['name']

            # Check compliance
            is_compliant = is_dns_1123_subdomain_compliant(generated_name)

            print(f"File: {test_case['file']}")
            print(f"  Original name: '{original_name}'")
            print(f"  Generated name: '{generated_name}'")
            print(f"  DNS-1123 compliant: {is_compliant}")
            print()

            # Verify that the original test expects the problematic name
            if original_name == test_case['expected_original_name']:
                print(f"  ✓ Confirmed original name matches expected")
            else:
                print(f"  ✗ Warning: Expected '{test_case['expected_original_name']}', got '{original_name}'")

        except Exception as e:
            print(f"Error processing {test_case['file']}: {e}")
            print()

def test_good_datasets():
    """Test datasets that should already be compliant."""

    test_cases = [
        {
            'file': 'dax-data-set-descriptors/publaynet.yaml',
            'expected_original_name': 'PubLayNet'
        },
        {
            'file': 'dax-data-set-descriptors/pubtabnet.yaml', 
            'expected_original_name': 'PubTabNet'
        },
        {
            'file': 'dax-data-set-descriptors/tsc.yaml',
            'expected_original_name': 'TensorFlow Speech Commands'
        }
    ]

    print("\nTesting datasets with potentially good names...")
    print("=" * 60)

    for test_case in test_cases:
        try:
            # Load the input YAML
            input_yaml = yaml.load(open(test_case['file']))
            original_name = input_yaml['name']

            # Generate DLF YAML
            dlf_dict = generate_dlf_yaml_dict(input_yaml)
            generated_name = dlf_dict['metadata']['name']

            # Check compliance
            is_compliant = is_dns_1123_subdomain_compliant(generated_name)

            print(f"File: {test_case['file']}")
            print(f"  Original name: '{original_name}'")
            print(f"  Generated name: '{generated_name}'")
            print(f"  DNS-1123 compliant: {is_compliant}")
            print()

        except Exception as e:
            print(f"Error processing {test_case['file']}: {e}")
            print()

if __name__ == "__main__":
    test_problematic_datasets()
    test_good_datasets()
